// Dates are UTC day integers. Calendar year starts are generated by Python,
// so the browser never invents a second leap-year/epoch implementation.
export const DAY=86400000;
export const dayNumber=iso=>Math.floor(Date.parse(iso+'T00:00:00Z')/DAY);
export const isoDate=n=>new Date(n*DAY).toISOString().slice(0,10);
export function toEgyptian(day,years){
 let lo=0,hi=years.length-1;
 while(lo+1<hi){const mid=(lo+hi)>>1;if(dayNumber(years[mid].start)<=day)lo=mid;else hi=mid;}
 const y=years[lo],offset=day-dayNumber(y.start);
 if(offset<0||offset>=y.days)throw new RangeError('Date outside supported calendar');
 return {year:y.year,month:offset<360?Math.floor(offset/30)+1:13,day:offset<360?offset%30+1:offset-359};
}
export function toGregorian(e,years){
 const y=years.find(y=>y.year===e.year);
 const limit=e.month===13?y?.days-360:30;
 if(!y||e.month<1||e.month>13||e.day<1||e.day>limit)throw new RangeError('Invalid Egyptian date');
 return dayNumber(y.start)+(e.month===13?360:(e.month-1)*30)+e.day-1;
}
export function nativeNumber(n,lang){
 if(lang==='ar')return String(n).replace(/[0-9]/g,x=>'٠١٢٣٤٥٦٧٨٩'[Number(x)]);
 if(lang==='egy'){
  const groups=[[1000,'𓆼'],[100,'𓍢'],[10,'𓎆'],[1,'𓏺']];let s='';
  for(const [v,c] of groups){s+=c.repeat(Math.floor(n/v));n%=v;}return s;
 }
 const units=['','ⲁ','ⲃ','ⲅ','ⲇ','ⲉ','ⲋ','ⲍ','ⲏ','ⲑ'],tens=['','ⲓ','ⲕ','ⲗ','ⲙ','ⲛ','ⲝ','ⲟ','ⲡ','ϥ'],hundreds=['','ⲣ','ⲥ','ⲧ','ⲩ','ⲫ','ⲭ','ⲯ','ⲱ','ⳁ'];
 let s='';if(n>=1000){s='͵'+units[Math.floor(n/1000)]+'̅';n%=1000;}
 for(const [v,a] of [[100,hundreds],[10,tens],[1,units]]){const q=Math.floor(n/v);if(q)s+=a[q]+'̅';n%=v;}return s;
}
export function monthGrid(year,month,week,years){
 const start=toGregorian({year,month,day:1},years),y=years.find(y=>y.year===year);
 const length=month===13?y.days-360:30;
 const pad=week===7?(new Date(start*DAY).getUTCDay()+6)%7:0;
 const cells=Array(pad).fill(null);
 for(let d=1;d<=length;d++)cells.push({day:d,gregorian:start+d-1});
 while(cells.length%week)cells.push(null);
 return cells;
}
export function festivalHits(day,years,festivals){
 const e=toEgyptian(day,years);const hits=[];
 for(const f of festivals){
  for(const year of [e.year-1,e.year]){
   if(!years.some(y=>y.year===year))continue;
   // The sixth epagomenal day is absent from a common year.
   let start;try{start=toGregorian({year,month:f.month,day:f.day},years);}catch{continue;}
   if(day>=start&&day<start+f.duration){hits.push({...f,start,end:start+f.duration});break;}
  }
 }return hits;
}
